<?php require_once "../config/auth.php";require_admin();$p=db();$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$id=(int)$_POST["id"];$a=$_POST["action"];$p->beginTransaction();try{$q=$p->prepare("SELECT * FROM deposits WHERE id=? FOR UPDATE");$q->execute([$id]);$d=$q->fetch();if(!$d||$d["status"]!=="pending")throw new Exception("Already reviewed.");if($a==="approve"){$p->prepare("UPDATE users SET balance=balance+? WHERE id=?")->execute([$d["amount"],$d["user_id"]]);$p->prepare("INSERT INTO transactions(user_id,type,amount,description) VALUES(?,'deposit',?,'Deposit approved')")->execute([$d["user_id"],$d["amount"]]);$p->prepare("UPDATE deposits SET status='approved',reviewed_at=NOW() WHERE id=?")->execute([$id]);}else{$p->prepare("UPDATE deposits SET status='rejected',reviewed_at=NOW() WHERE id=?")->execute([$id]);}$p->commit();$msg="Updated.";}catch(Exception $e){$p->rollBack();$msg=$e->getMessage();}}$rows=$p->query("SELECT d.*,u.username FROM deposits d JOIN users u ON u.id=d.user_id ORDER BY d.id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../public/style.css"></head><body><main><h1>Deposits</h1><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="table"><table><tr><th>ID</th><th>User</th><th>Amount</th><th>Method</th><th>TXID</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["username"])?></td><td>৳<?=$r["amount"]?></td><td><?=e($r["method"])?></td><td><?=e($r["transaction_id"])?></td><td><?=$r["status"]?></td><td><?php if($r["status"]==="pending"):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r["id"]?>"><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></main></body></html>